document.addEventListener("DOMContentLoaded",()=>{const e=[{year:"1847",title:"Birth",description:"Born Annie Wood on October 1 in London, England."},{year:"1867",title:"Marriage",description:"Married clergyman Frank Besant; the couple later separated over her growing religious and political independence."},{year:"1889",title:"Turn to Theosophy",description:"Joined the Theosophical Society after reviewing H.P. Blavatsky's 'The Secret Doctrine', beginning her lifelong spiritual engagement with India."},{year:"1893",title:"Arrival in India",description:"Travelled to India for the first time as a leader of the Theosophical Society, and later settled at its headquarters in Adyar, Madras."},{year:"1898",title:"Central Hindu College",description:"Founded the Central Hindu College in Banaras, which later formed the nucleus of Banaras Hindu University."},{year:"1907",title:"Theosophical Society President",description:"Elected President of the Theosophical Society, a position she held until her death."},{year:"1916",title:"All India Home Rule League",description:"Founded the All India Home Rule League at Madras on 1 September, campaigning for dominion status for India through her newspapers and public meetings."},{year:"1917",title:"Internment & Congress Presidency",description:"Interned by the Madras government under the Defence of India Act in June; released in September amid nationwide protest, and elected the first woman President of the Indian National Congress in December."},{year:"1920",title:"Break with Congress Strategy",description:"Opposed Gandhi's Non-Cooperation and Satyagraha campaign at the Congress session, a stance that saw her political influence decline."},{year:"1933",title:"Death",description:"Passed away on September 20 at Adyar, Madras, where she had lived for much of her adult life."}],n=document.getElementById("timeline-container");n&&e.forEach(e=>{const a=document.createElement("div");a.className="timeline-item",a.tabIndex=0,a.innerHTML=`\n                <div class="timeline-year">${e.year}</div>\n                <div class="timeline-content">\n                    <h3>${e.title}</h3>\n                    <p>${e.description}</p>\n                </div>\n            `,n.appendChild(a)});const a=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1});document.querySelectorAll(".timeline-item").forEach(e=>a.observe(e));const t=[{title:"All India Home Rule League",desc:"Founded at Madras on 1 September 1916, growing to roughly 200 branches across most of India, working alongside Tilak's separate Home Rule League in Maharashtra."},{title:"Uniting Moderates & Extremists",desc:"Worked to bring Congress Moderates, Extremists, and the Muslim League behind a shared demand for self-government, helping revive nationalist politics after a period of inactivity."},{title:"Mass Public Campaigning",desc:"Toured extensively delivering public lectures and organizing meetings and conferences to build political awareness in areas like Sindh, Punjab, Gujarat, Bihar, and the United Provinces."},{title:"Congress Presidency",desc:"Elected President of the Indian National Congress in December 1917 — the first woman to hold the position — following the wave of sympathy after her internment."}],i=document.getElementById("movement-container");i&&t.forEach(e=>{const n=document.createElement("div");n.className="contribution-card",n.tabIndex=0,n.innerHTML=`\n                <h3>${e.title}</h3>\n                <p>${e.desc}</p>\n            `,i.appendChild(n)});const r=[{name:"New India",lang:"English",desc:"A daily newspaper Besant used as the primary mouthpiece of the Home Rule Movement, campaigning for Indian self-government and later banned during her 1917 internment."},{name:"Commonweal",lang:"English",desc:"A Madras-based weekly journal that carried her political writings and helped spread the case for Home Rule to a wider audience."}],o=document.getElementById("publications-container");o&&r.forEach(e=>{const n=document.createElement("div");n.className="newspaper-card",n.tabIndex=0,n.innerHTML=`\n                <div class="newspaper-name">${e.name}</div>\n                <div class="newspaper-lang">${e.lang}</div>\n                <p>${e.desc}</p>\n            `,o.appendChild(n)});const s=[{caption:"Annie Besant addressing a public meeting during the Home Rule campaign",alt:"Annie Besant speaking to a crowd at a public political meeting"},{caption:"The Theosophical Society headquarters at Adyar, Madras, where Besant lived and worked",alt:"Historic buildings and gardens of the Theosophical Society campus at Adyar"},{caption:"Central Hindu College, Banaras, founded by Besant in 1898",alt:"Facade of the historic Central Hindu College building in Banaras"},{caption:"A copy of New India, the newspaper Besant used to campaign for Home Rule",alt:"Front page of a historic English-language Indian newspaper"}],d=document.getElementById("gallery-container");d&&s.forEach(e=>{const n=document.createElement("figure");n.className="gallery-card",n.tabIndex=0,n.innerHTML=`\n                <div class="gallery-placeholder" role="img" aria-label="${e.alt}">🖼️</div>\n                <figcaption>${e.caption}</figcaption>\n            `,d.appendChild(n)});const l=document.getElementById("legacy-container");l&&(l.innerHTML='<div class="content-card" tabindex="0"><p>Annie Besant is remembered as a rare figure who bridged the Moderate and Extremist eras of Indian nationalism and helped set the stage for the mass movements of the Gandhian period that followed. Her internment in 1917 turned public opinion sharply in favour of self-government, and her election as the first woman President of the Indian National Congress remains a landmark in the movement\'s history. Though her later opposition to Gandhi\'s methods cost her influence, her decades of work in education, journalism, and political organizing left a lasting mark on India\'s path to independence.</p></div>');const c=[{text:"Indian National Congress — Annie Besant, Past Party Presidents",link:"https://inc.in/leadership/past-party-presidents/annie-besant"},{text:"Wikipedia — Annie Besant",link:"https://en.wikipedia.org/wiki/Annie_Besant"},{text:"Wikipedia — Indian Home Rule Movement",link:"https://en.wikipedia.org/wiki/Indian_Home_Rule_movement"},{text:"1914-1918-Online: International Encyclopedia of the First World War — Besant, Annie",link:"https://encyclopedia.1914-1918-online.net/article/besant-annie/"}],h=document.getElementById("references-container");h&&c.forEach(e=>{const n=document.createElement("li");n.innerHTML="#"!==e.link?`<a href="${e.link}" target="_blank" rel="noopener noreferrer">${e.text}</a>`:`<span>${e.text}</span>`,h.appendChild(n)})});